using System.Text;
using GoymenERP.DocumentGeneration.Pdf;
using UglyToad.PdfPig;

namespace GoymenERP.DocumentGeneration.Pdf.Tests;

/// <summary>
/// The multi-page business document layout (MOD-07 sales order PDF): text is read back from the generated bytes, never
/// assumed. Every name and value here is SENTETIK.
/// </summary>
public sealed class DocumentPdfGeneratorTests
{
    private const string PageLabel = "Sayfa {0} / {1}";
    private const string Footer = "SENTETIK — bilgi amaçlı teknik çıktı";

    [Fact]
    public void A_long_table_continues_on_landscape_pages_with_its_header_and_every_row_read_back()
    {
        var rows = Enumerable.Range(1, 120)
            .Select(index => (IReadOnlyList<string>)[index.ToString("D3", System.Globalization.CultureInfo.InvariantCulture), $"Ürün İğdeş {index}", "1.25"])
            .ToArray();
        var request = Request(
            [
                new DocumentPdfHeading("Satırlar"),
                new DocumentPdfTable(
                    [new DocumentPdfColumn("Sıra", 1), new DocumentPdfColumn("Ürün adı", 5), new DocumentPdfColumn("Miktar", 2, DocumentPdfAlignment.End)],
                    rows),
            ]);

        var artifact = new DocumentPdfGenerator().Generate(request);

        Assert.Equal("application/pdf", artifact.MediaType);
        Assert.Equal("%PDF-", Encoding.ASCII.GetString(artifact.Content, 0, 5));
        Assert.Equal(PdfVisibleFileName.Build(request.FileNameParts), artifact.VisibleFileName);
        using var pdf = PdfDocument.Open(artifact.Content);
        var pages = pdf.GetPages().ToArray();
        Assert.True(pages.Length > 1, "120 rows cannot fit on one page.");
        var text = string.Concat(pages.Select(page => page.Text));
        foreach (var (page, index) in pages.Select((page, index) => (page, index)))
        {
            Assert.InRange(page.Width, 841.8, 842.0);
            Assert.InRange(page.Height, 595.2, 595.4);
            Assert.Contains($"Sayfa {index + 1} / {pages.Length}", page.Text, StringComparison.Ordinal);
            Assert.Contains(Footer, page.Text, StringComparison.Ordinal);
            // The header row repeats on every page the table continues on.
            Assert.Contains("SıraÜrün adıMiktar", page.Text, StringComparison.Ordinal);
        }

        Assert.StartsWith("SENTETIK Satış Siparişi SO-2026-000123", pages[0].Text, StringComparison.Ordinal);
        foreach (var row in rows)
        {
            Assert.Contains(string.Concat(row), text, StringComparison.Ordinal);
        }

        Assert.Contains(pages[0].Letters, letter =>
            letter.FontName?.Contains("Noto Sans Regular", StringComparison.OrdinalIgnoreCase) == true);
        var pdfSyntax = Encoding.Latin1.GetString(artifact.Content);
        Assert.Contains("/FontFile2", pdfSyntax, StringComparison.Ordinal);
        Assert.Contains("/ToUnicode", pdfSyntax, StringComparison.Ordinal);
        Assert.DoesNotContain("/JavaScript", pdfSyntax, StringComparison.Ordinal);
        Assert.DoesNotContain("/OpenAction", pdfSyntax, StringComparison.Ordinal);
        Assert.DoesNotContain("/Launch", pdfSyntax, StringComparison.Ordinal);
        Assert.DoesNotContain("/EmbeddedFiles", pdfSyntax, StringComparison.Ordinal);
        Assert.DoesNotContain("/Subtype /Image", pdfSyntax, StringComparison.Ordinal);
        TechnicalPdfGeneratorTests.AssertNoHostIdentifiers(pdf, artifact.Content,
            Environment.UserName, Environment.MachineName, Directory.GetCurrentDirectory());
    }

    [Fact]
    public void Fields_and_paragraphs_keep_turkish_text_and_a_word_wider_than_its_column_is_wrapped_not_cut()
    {
        var longWord = string.Concat(Enumerable.Repeat("İŞĞÜÖÇışğüöç", 30));
        var request = Request(
            [
                new DocumentPdfFields([new DocumentPdfField("Müşteri", "SENTETIK Çağdaş Gıda A.Ş."), new DocumentPdfField("Not", longWord)]),
                new DocumentPdfParagraph("İlk satır\r\nİkinci satır‏\u0007son"),
            ]);

        var artifact = new DocumentPdfGenerator().Generate(request);

        using var pdf = PdfDocument.Open(artifact.Content);
        var text = Assert.Single(pdf.GetPages()).Text;
        Assert.Contains("MüşteriSENTETIK Çağdaş Gıda A.Ş.", text, StringComparison.Ordinal);
        // Wrapped across several lines, every letter is still there and in order.
        Assert.Contains(longWord, text, StringComparison.Ordinal);
        // The hard line break starts a line; the format mark is dropped and the bell is a space.
        Assert.Contains("İlk satırİkinci satır son", text, StringComparison.Ordinal);
        Assert.True(text.IsNormalized(NormalizationForm.FormC));
    }

    [Fact]
    public void Generation_refuses_a_row_taller_than_a_page_instead_of_cutting_it()
    {
        var tall = string.Join('\n', Enumerable.Repeat("satır", 80));
        var request = Request([new DocumentPdfTable([new DocumentPdfColumn("Not", 1)], [[tall]])]);

        var exception = Assert.Throws<ArgumentException>(() => new DocumentPdfGenerator().Generate(request));

        Assert.Contains("taller than one page", exception.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Generation_refuses_more_pages_than_its_bound()
    {
        var rows = Enumerable.Range(0, 5_000).Select(_ => (IReadOnlyList<string>)["a\nb\nc"]).ToArray();
        var request = Request([new DocumentPdfTable([new DocumentPdfColumn("Not", 1)], rows)]);

        var exception = Assert.Throws<ArgumentException>(() => new DocumentPdfGenerator().Generate(request));

        Assert.Contains("page limit", exception.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Generation_refuses_malformed_requests_before_any_layout()
    {
        var generator = new DocumentPdfGenerator();
        var column = new DocumentPdfColumn("Not", 1);

        Assert.Throws<ArgumentException>(() => generator.Generate(Request([]) with { TechnicalId = Guid.Empty }));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([]) with { Title = " " }));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([]) with { PageLabelFormat = "Sayfa {0}" }));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([]) with { PageLabelFormat = "Sayfa {0} / {1} {2}" }));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([new DocumentPdfTable([column], [["a", "b"]])])));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([new DocumentPdfTable([column with { Weight = 0 }], [])])));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([new DocumentPdfTable([column with { Weight = double.NaN }], [])])));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([new DocumentPdfTable([column], [[null!]])])));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([new DocumentPdfFields([])])));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([null!])));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([new DocumentPdfTable(
            Enumerable.Repeat(column, 17).ToArray(), [])])));
        Assert.Throws<ArgumentException>(() => generator.Generate(Request([new DocumentPdfTable(
            [column], Enumerable.Repeat((IReadOnlyList<string>)["a"], 5_001).ToArray())])));
        var raw = Assert.Throws<ArgumentException>(() => generator.Generate(Request([new DocumentPdfParagraph(new string('A', 4_097))])));
        Assert.Contains("raw input limit", raw.Message, StringComparison.Ordinal);
        var footer = Assert.Throws<ArgumentException>(() => generator.Generate(Request([]) with { FooterText = new string('İ', 400) }));
        Assert.Contains("footer", footer.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void An_end_aligned_cell_is_drawn_against_its_column_end()
    {
        var request = Request([new DocumentPdfTable(
            [new DocumentPdfColumn("Ad", 1), new DocumentPdfColumn("Tutar", 1, DocumentPdfAlignment.End)],
            [["SENTETIK", "42"]])]);

        var artifact = new DocumentPdfGenerator().Generate(request);

        using var pdf = PdfDocument.Open(artifact.Content);
        var page = Assert.Single(pdf.GetPages());
        var start = page.Letters.First(letter => letter.Value == "S" && letter.BoundingBox.Left < page.Width / 2);
        var end = page.Letters.Last(letter => letter.Value == "2");
        // Two equal columns over the 36 pt margins: the end-aligned value ends close to the right margin.
        Assert.InRange(start.BoundingBox.Left, 36, 45);
        Assert.InRange(end.BoundingBox.Right, page.Width - 36 - 10, page.Width - 36);
    }

    private static DocumentPdfRequest Request(IReadOnlyList<DocumentPdfBlock> blocks) => new(
        Guid.Parse("8f3a4c55-2d7e-4b8f-9a61-0c1d2e3f4a5b"),
        new PdfDocumentFileNameParts("Satış Siparişi", "SO-2026-000123", "SENTETIK Cari", new DateOnly(2026, 10, 27), 1, "Onaylı"),
        "SENTETIK Satış Siparişi SO-2026-000123",
        blocks,
        Footer,
        PageLabel);
}
